# Function to send health report
send_health_report() {
    local service_3000_status=$1
    local service_8080_status=$2
    local env_vars=$3

    # Convert status numbers to boolean
    local s1_healthy=$([ "$service_3000_status" -eq 0 ] && echo "true" || echo "false")
    local s2_healthy=$([ "$service_8080_status" -eq 0 ] && echo "true" || echo "false")

    # Build JSON payload
    local payload=$(jq -n \
        --argjson s1_healthy "$s1_healthy" \
        --argjson s2_healthy "$s2_healthy" \
        --argjson env "$env_vars" \
        '{
          "services": {
            "service_3000": {
              "port": 3000,
              "healthy": $s1_healthy
            },
            "service_8080": {
              "port": 8080,
              "healthy": $s2_healthy
            }
          },
          "environment": $env,
          "timestamp": (now | todateiso8601)
        }')

