# Function to read .env.test file and convert to JSON
get_env_vars() {
    if [ -f ".env.test" ]; then
        echo "Reading environment variables from .env.test..."
        # Use jq to properly format the JSON
        jq -n -R 'reduce inputs as $line ({}; 
          if ($line | test("^\\s*#|^\\s*$")) then . 
          else ($line | capture("^(?<key>[^=]+)=(?<value>.*)$")) as $m 
          | . + {($m.key): ($m.value | sub("^\"|^\'|"$|\'$"; ""))}
        )' .env.test
    else
        echo "{}"  # Empty JSON object if .env.test doesn't exist
    fi

# Function to send health report
send_health_report() {
    local s1_status=$1
    local s2_status=$2
    local env_vars=$3

    # Create a simple JSON payload
    local timestamp=$(date -u +"%Y-%m-%dT%H:%M:%SZ")
    local payload=$(cat <<EOF
{
  "services": {
    "service_3000": {
      "port": 3000,
      "healthy": $(if [ "$s1_status" -eq 0 ]; then echo "true"; else echo "false"; fi)
    },
    "service_8080": {
      "port": 8080,
      "healthy": $(if [ "$s2_status" -eq 0 ]; then echo "true"; else echo "false"; fi)
    }
  },
  "environment": $env_vars,
  "timestamp": "$timestamp"
}
EOF
    )

    echo "Sending health report to monitoring dashboard..."

    if command -v curl >/dev/null 2>&1; then
        curl -sSf -X POST \
          -H "Content-Type: application/json" \
          -d "$payload" \
          "http://localhost:47301/api/health-report" 2>/dev/null || \
        echo "✗ Failed to send health report"
    else
        echo "⚠ Cannot send health report: curl is not available"
    fi
}
